// === VERBATIM JS from the demo's iframe srcdoc (pen.js) ===
// Loaded scripts:
//   <script src='https://s3-us-west-2.amazonaws.com/s.cdpn.io/16327/gsap-latest-beta.min.js'></script>
//   <script src='https://s3-us-west-2.amazonaws.com/s.cdpn.io/16327/ScrollToPlugin3.min.js'></script>
// NOTE: the demo does NOT show an explicit gsap.registerPlugin(ScrollToPlugin) — it relies on the
// global side-effect of loading ScrollToPlugin3.min.js after gsap. In a module/Next.js project
// you MUST register it explicitly (see React port below).

document.querySelectorAll("nav button").forEach((btn, index) => {
  btn.addEventListener("click", () => {
    gsap.to(window, { duration: 1, scrollTo: { y: "#section" + (index + 1), offsetY: 120 } });
  });
});
