"use client";
import { useEffect } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollToPlugin } from "gsap/ScrollToPlugin";

gsap.registerPlugin(useGSAP, ScrollToPlugin);

/**
 * Smoothly animate the window scroll to a saved reading position.
 * Drop-in upgrade for the `window.scrollTo({ top, behavior: "instant" })`
 * call at line 119 of frontend/lib/useReadingPosition.ts.
 *
 * Behavior parity with the GSAP demo:
 *   - ScrollToPlugin (free, core plugin — NOT a Club GSAP paid plugin)
 *   - duration: 1.1s   (demo uses 1; reading-restore feels slightly better at 1.1)
 *   - ease:     power2.inOut  (demo omits ease → defaults to power1.out; we upgrade)
 *   - autoKill: true   (default for window targets — user scroll instantly aborts tween)
 *   - prefers-reduced-motion → instant jump fallback
 */
export function smoothRestoreScroll(
  targetY: number,
  opts?: { onSettled?: () => void },
) {
  if (typeof window === "undefined") return;

  const reduced = window.matchMedia?.(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (reduced) {
    window.scrollTo({ top: targetY, behavior: "instant" as ScrollBehavior });
    opts?.onSettled?.();
    return;
  }

  // rAF settles layout (images, fonts) before measuring/animating —
  // mirrors the existing rAF guard in useReadingPosition.ts (~line 96).
  requestAnimationFrame(() => {
    gsap.to(window, {
      scrollTo: { y: targetY, autoKill: true },
      duration: 1.1,
      ease: "power2.inOut",
      overwrite: "auto",
      onAutoKill: () => opts?.onSettled?.(),
      onComplete: () => opts?.onSettled?.(),
      onInterrupt: () => opts?.onSettled?.(),
    });
  });
}

/* --------------------------------------------------------------
 * useGSAP variant — call from inside a "use client" component
 * so the tween is auto-cleaned on unmount / strict-mode rerun.
 * -------------------------------------------------------------- */
export function useSmoothRestoreOnMount(
  targetY: number | null,
  ready: boolean,
) {
  useGSAP(
    () => {
      if (!ready || targetY == null) return;
      const reduced = window.matchMedia?.(
        "(prefers-reduced-motion: reduce)",
      ).matches;
      if (reduced) {
        window.scrollTo({ top: targetY, behavior: "instant" as ScrollBehavior });
        return;
      }
      gsap.to(window, {
        scrollTo: { y: targetY, autoKill: true },
        duration: 1.1,
        ease: "power2.inOut",
      });
    },
    { dependencies: [ready, targetY] },
  );
}
